private static readonly string[] HotInputPaths =
[
    "game_state/player/status_changes.json", "game_state/player/experience.json",
    "game_state/core/player_status.json", "game_state/meta/soul_state.json",
    "game_state/misc/characteristics.json", "game_state/player/stat_points.json"
];
private static readonly string[] HotOutputPaths =
    ["output/narrative_response.json", "output/interface_updates.json", "output/debug_logs.json"];
private static readonly string[] HotControlPaths =
[
    PendingTurnSnapshotManifestPath, PendingTurnSnapshotAuthority.AuthorityPath,
    "input/turn_request.json", "game_state/control/validation_repair_request.json", "ready/turn_complete.json"

private void EndHotOrdinaryOriginal(string reason)
{
    if (_hotOrdinaryOriginal is { } origin) origin.State = "Ended";
    _hotRepairReady?.Fail(reason);
}

private void EnterHotOriginalProducer(HotOrdinaryOriginal owner, TurnRequest request)
{
    if (!ReferenceEquals(owner, _hotOrdinaryOriginal) || owner.State != "Beginning" || owner.ProducerEntered)
        throw new InvalidOperationException("Ordinary original producer requires its one actual Stage invocation.");
    owner.ProducerEntered = true; owner.ProducerRequest = request;
    owner.SessionId = request.SessionId; owner.RequestId = request.RequestId; owner.Turn = request.TurnNumber;
}

private void ObserveHotOriginalIssued(HotOrdinaryOriginal owner, FileSystemManager.CanonicalWriteLease lease,
    PendingTurnSnapshotManifest manifest, string manifestJson, string authorityJson)
{
    if (!ReferenceEquals(owner, _hotOrdinaryOriginal) || owner.State != "Beginning" || !owner.ProducerEntered ||
        manifest.SessionId != owner.SessionId || manifest.RequestId != owner.RequestId || manifest.TurnNumber != owner.Turn)
        throw new InvalidOperationException("The issued ordinary original does not belong to its Stage producer.");
    var generation = _fs.ReadLocalGenerationSnapshot(lease);
    if (generation.Binding.Id != owner.Generation || generation.Bytes is null)
        throw new SessionReplacedException("Ordinary staging generation changed.", owner.Generation, generation.Binding.Id);
    owner.GenerationBytes = generation.Bytes.ToArray();
    owner.ManifestBytes = FileSystemManager.EncodeUtf8WithPreamble(manifestJson);
    owner.AuthorityBytes = FileSystemManager.EncodeUtf8WithPreamble(authorityJson);
    owner.SnapshotToken = manifest.ManifestPayloadHash;
    // The canonical lease owns and disposes its child MainAdmission. Retain
    // the actual enclosing continuous operation, never that short child.
    owner.ConsoleOwner = owner.BrowserBinding is null ? lease.MainAdmission?.Parent : null;
    owner.State = "Issued";
}

private void CompleteHotOriginalStaging(PlayerTurnPreparation preparation)
{
    var owner = preparation.HotOrigin ?? throw new InvalidOperationException("Actual Stage origin is missing.");
    if (!ReferenceEquals(owner, _hotOrdinaryOriginal) || owner.State != "Issued" ||
        preparation.Generation != owner.Generation || preparation.Request.SessionId != owner.SessionId ||
        preparation.Request.RequestId != owner.RequestId || preparation.Request.TurnNumber != owner.Turn ||
        preparation.SnapshotContext.Payload.ManifestPayloadHash != owner.SnapshotToken)
        throw new InvalidOperationException("Stage returned a different original or request.");
    owner.RequestBytes = FileSystemManager.EncodeUtf8WithPreamble(preparation.HotRequestJson!);
    owner.Preparation = preparation;
    // Console remains under its continuous owner. Browser must also return
    // through the real outer participating close before it becomes usable.
    owner.State = owner.BrowserBinding is null ? "StagedUnderLiveOwner" : "AwaitingStagingOwnerReturn";
}

private void AcknowledgeHotBrowserStaging(PlayerTurnPreparation preparation)
{
    var owner = preparation.HotOrigin;
    if (owner is null || !ReferenceEquals(owner, _hotOrdinaryOriginal) ||
        !ReferenceEquals(owner.Preparation, preparation) || owner.State != "AwaitingStagingOwnerReturn")
        throw new InvalidOperationException("Browser Stage acknowledgement requires its actual returned preparation.");
    owner.State = "Staged";
}

private void RequireHotOrigin(FileSystemManager.CanonicalWriteLease lease, HotOrdinaryOriginal origin)
{
    RequireOrdinaryJointRepairLease(lease);
    _fs.EnsureCanonicalWriteLeaseActive(lease);
    var main = lease.MainAdmission ?? throw new InvalidDataException("HOT requires actual ordinary Main admission.");
    main.Validate(lease);
    var generation = _fs.ReadLocalGenerationSnapshot(lease);
    if (generation.Binding.Id != origin.Generation)
        throw new SessionReplacedException("HOT original belongs to a replaced session.", origin.Generation, generation.Binding.Id);
    if (!ReferenceEquals(origin, _hotOrdinaryOriginal) || origin.Preparation is null ||
        origin.State is not ("Staged" or "StagedUnderLiveOwner") || !HotBytesEqual(generation.Bytes, origin.GenerationBytes))
        throw new InvalidDataException("The actual live ordinary original is unavailable.");
    if (origin.BrowserBinding is { } browser)
    {
        if (!_fs.HasBrowserOriginalOperation) throw new InvalidDataException("Current browser original admission is missing.");
        _ = _fs.CaptureBrowserOriginalCondition(lease, browser.Generation);
    }
    else if (origin.ConsoleOwner is not { Closed: false } console || !main.SharesAccess(console))
        throw new InvalidDataException("The continuous console staging owner is no longer current.");

private async Task CaptureMatchingHotRepairReadyAsync(HotRepairReadyRead read, ValidationRepairReady ready,
    PendingTurnSnapshotResolution resolution, string generation, bool workerRoute)
{
    if (read.Origin is null) { read.Fail("MissingLiveOrigin"); return; }
    if (workerRoute) { read.Fail("WorkerDispositionNotIntegrated"); return; }
    try
    {
        await using var lease = await _fs.AcquireCanonicalWriteLeaseAsync();
        ThrowIfRepairSessionReplaced(lease, generation);
        if (!ReferenceEquals(read, _hotRepairReady) || resolution.Context is not { } frame ||
            !IsMatchingRepairReady(ready, frame)) throw new InvalidDataException("HOT matching branch changed.");
        var source = await ReadHotSourceAsync(lease, read.Origin, frame);
        if (!HotBytesEqual(read.Bytes, await _fs.ReadFileBytesAsync(lease, ValidationRepairReadyPath)))
            throw new InvalidDataException("Ready changed after its actual read.");
        source.Evidence.RequireCurrent(_fs, lease, source.Snapshot);
        await RequireHotCurrentImagesAsync(lease, source.Current);
        read.Source = source;
        read.Status = "MatchingReadyObserved";
    }
    catch (Exception error)
    {
        read.Fail(IsOptionalHotFailure(error) ? "SourceChanged" : "OwnerFailure");
        if (!IsOptionalHotFailure(error)) throw;
    }
}

private async Task<HotSourceObservation> ReadHotSourceAsync(FileSystemManager.CanonicalWriteLease lease,
    HotOrdinaryOriginal origin, ValidatedPendingTurnSnapshotContext frame)
{
    RequireHotOrigin(lease, origin);
    var observed = PendingTurnSnapshotReader.ReadObservedCurrent(_fs, lease, new PendingTurnSnapshotPathSelection(
        ["game_state/meta/soul_state.json"], HotInputPaths.Where(path => path != "game_state/meta/soul_state.json")));
    if (!observed.Success || observed.Snapshot is not { } original || observed.Evidence is not { } evidence)
        throw new InvalidDataException("HOT original source closure is unavailable.");
    if (original.SessionId != origin.SessionId || original.RequestId != origin.RequestId ||
        original.SnapshotToken != origin.SnapshotToken || original.TurnNumber != origin.Turn ||
        original.SessionId != frame.SessionId || original.RequestId != frame.RequestId ||
        original.SnapshotToken != frame.Payload.ManifestPayloadHash || original.TurnNumber != frame.TurnNumber)
        throw new InvalidDataException("HOT source is not the actual Stage original.");
    var current = new Dictionary<string, byte[]?>(StringComparer.Ordinal);
    foreach (var path in HotInputPaths.Concat(HotOutputPaths).Concat(HotControlPaths))
        current.Add(path, await _fs.ReadFileBytesAsync(lease, path));
    if (!HotBytesEqual(current[PendingTurnSnapshotManifestPath], origin.ManifestBytes) ||
        !HotBytesEqual(current[PendingTurnSnapshotAuthority.AuthorityPath], origin.AuthorityBytes) ||
        !HotBytesEqual(current["input/turn_request.json"], origin.RequestBytes))
        throw new InvalidDataException("HOT original or final Stage request changed.");
    var rows = new JsonArray();
    foreach (var path in HotInputPaths)
    {
        var present = original.CoveredLogicalPaths.Contains(path, StringComparer.Ordinal);
        var absent = original.AbsentLogicalPaths.Contains(path, StringComparer.Ordinal);
        rows.Add(new JsonObject { ["path"] = path,
            ["sourceStatus"] = present ? "Present" : absent ? "Absent" : "UncoveredInSignedInventory",
            ["present"] = present ? true : absent ? false : null,
            ["base64"] = present ? Convert.ToBase64String(original.ReadRequiredBytes(path)) : null });
    }
    evidence.RequireCurrent(_fs, lease, original);
    await RequireHotCurrentImagesAsync(lease, current);
    RequireHotOrigin(lease, origin);
    return new(original, evidence, evidence.ExportDiagnosticData(), current, rows);
}

private async Task RequireHotCurrentImagesAsync(FileSystemManager.CanonicalWriteLease lease,
    IReadOnlyDictionary<string, byte[]?> images)
{
    foreach (var (path, bytes) in images)
        if (!HotBytesEqual(bytes, await _fs.ReadFileBytesAsync(lease, path)))
            throw new InvalidDataException("HOT source changed during physical recheck: " + path);
}

private async Task RecheckHotReadySourceAsync(FileSystemManager.CanonicalWriteLease lease, HotRepairReadyRead read,
    bool requireReadyAbsent)
{
    if (read.Faulted || read.Source is not { } previous || read.Origin?.Preparation is not { } preparation)
        throw new InvalidDataException("HOT has no closed matching source observation.");
    var fresh = await ReadHotSourceAsync(lease, read.Origin, preparation.SnapshotContext);
    if (!JsonNode.DeepEquals(fresh.OriginalOperations, previous.OriginalOperations))
        throw new InvalidDataException("HOT original operations changed between actual leases.");
    foreach (var (path, bytes) in previous.Current)
        if (!HotBytesEqual(bytes, fresh.Current[path])) throw new InvalidDataException("HOT submitted source changed: " + path);
    var ready = await _fs.ReadFileBytesAsync(lease, ValidationRepairReadyPath);
    if (requireReadyAbsent ? ready is not null : !HotBytesEqual(ready, read.Bytes))
        throw new InvalidDataException("HOT Ready no longer matches its actual consumption event.");
    fresh.Evidence.RequireCurrent(_fs, lease, fresh.Snapshot);
    await RequireHotCurrentImagesAsync(lease, fresh.Current);
    // Only this new lease's genuinely issued reader evidence is retained.

private JsonObject HotCustodyDiagnostic(HotRepairReadyRead? read) => new()
{
    ["status"] = read?.Status ?? "Unavailable", ["reason"] = read?.Reason ?? (_hotRepairRoute == HotRepairRoute.Worker ? "WorkerDispositionNotIntegrated" :
        _hotRepairRoute == HotRepairRoute.DiagnosticOnly ? "DiagnosticOnlyDispatch" :
        _hotOrdinaryOriginal?.Preparation is not null ? "MatchingConsumptionNotCompleted" : "MissingLiveOrigin"),
    ["readyObservedBeforeDelete"] = read?.ReadyObservedBeforeDelete ?? false,
    ["readyDeleteReturned"] = read?.ReadyDeleteReturned ?? false,
    ["readyReleaseReturned"] = read?.ReadyReleaseReturned ?? false,
    ["currentSourceRecheckSucceeded"] = read?.CurrentSourceRecheckSucceeded ?? false,
    ["originalInputs"] = read?.Source?.OriginalInputs.DeepClone() ?? new JsonArray(),
    ["currentInputs"] = HotImageRows(HotInputPaths, read?.Source?.Current),
    ["outputs"] = HotImageRows(HotOutputPaths, read?.Source?.Current)
};

private JsonObject ExportHotOrdinarySubmissionDiagnostic() => new()
{
    ["binding"] = HotBindingDiagnostic(_hotOrdinaryOriginal), ["custody"] = HotCustodyDiagnostic(_hotRepairReady),
    ["hasS"] = false, ["hasB"] = false, ["hasM3"] = false

internal sealed class MortalJointPublicationAttempt
{
    private readonly GameEngine _engine;
    private readonly FileSystemManager _files;
    private readonly FileSystemManager.CanonicalWriteLease _lease;
    private readonly string _generation;
    private readonly object _frame;
    private readonly MortalJointRepairCheckpoint.RejectedCapture _capture;
    private readonly Dictionary<JointAttemptStage, object> _stages = new();
    private object? _continuation, _reservation;
    private bool _capturing = true, _expired, _delegated;
    private string _phase = "Capturing";
    private JsonObject _binding, _custody;
    private AcceptedTurnAuthorityRegistry.JointUnattemptedCloseResult? _close;
    private PendingTurnSnapshotReadAuthority? _hotOriginal;
    private PendingTurnSnapshotReader.OriginalReadEvidence? _hotEvidence;
    internal MortalJointPublicationAttempt(object issuer, GameEngine engine, FileSystemManager files,
        FileSystemManager.CanonicalWriteLease lease, object actualFrame,
        MortalJointRepairCheckpoint.RejectedCapture actualCapture, JsonObject binding, JsonObject custody)
    {
        RequireIssuer(issuer);
        _engine = engine; _files = files; _lease = lease; _frame = actualFrame; _capture = actualCapture;
        _generation = files.ReadLocalGenerationSnapshot(lease).Binding.Id
            ?? throw new InvalidDataException("Joint attempt requires its existing physical generation.");
        _binding = binding.DeepClone().AsObject(); _custody = custody.DeepClone().AsObject();
    }
    private static void RequireIssuer(object issuer)
    {
        if (!ReferenceEquals(issuer, JointAttemptIssuer)) throw new InvalidOperationException("Joint attempt requires its actual engine issuer.");
    }
    internal bool Delegated => _delegated;
    internal bool Live => !_expired;
    internal bool CloseRecorded => _close is not null;
    internal object? Continuation => _continuation;
    internal object? Reservation => _reservation;
    internal string Generation => _generation;
    internal bool IsCurrentOwner(FileSystemManager files, FileSystemManager.CanonicalWriteLease lease) =>
        !_expired && ReferenceEquals(files, _files) && ReferenceEquals(lease, _lease) &&
        ReferenceEquals(_engine._mortalJointPublicationAttempt, this) && lease.IsActive;
    internal void RequireActualOwner(FileSystemManager files, FileSystemManager.CanonicalWriteLease lease)
    {
        if (!IsCurrentOwner(files, lease) || !files.IsCurrentSessionGeneration(lease, _generation))
            throw new InvalidDataException("The current joint attempt owner is unavailable.");
        _capture.EnsureCurrent(files, lease);
        if (_frame is not ValidatedPendingTurnSnapshotContext frame ||
            !_engine.MatchesMortalJointRepairFrame(frame, frame.TurnNumber))
            throw new InvalidDataException("Joint attempt lost its actual private admitted frame.");
    }
    internal void RetainHotSource(object issuer, PendingTurnSnapshotReadAuthority original,
        PendingTurnSnapshotReader.OriginalReadEvidence evidence)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (!_capturing || _hotOriginal is not null) throw new InvalidOperationException("HOT source requires the actual open capture.");
        evidence.RequireCurrent(_files, _lease, original);
        _hotOriginal = original; _hotEvidence = evidence;
    }
    internal void RequireMechanicalOriginalAgreement(FileSystemManager files,
        FileSystemManager.CanonicalWriteLease lease, PendingTurnSnapshotReadAuthority mechanical)
    {
        RequireActualOwner(files, lease);
        if (_hotOriginal is not { } hot || _hotEvidence is null) return;
        _hotEvidence.RequireCurrent(files, lease, hot);
        if (hot.SessionId != mechanical.SessionId || hot.RequestId != mechanical.RequestId ||
            hot.SnapshotToken != mechanical.SnapshotToken || hot.TurnNumber != mechanical.TurnNumber || hot.Realm != mechanical.Realm)
            throw new InvalidDataException("The two genuine original operations belong to different sources.");
        foreach (var path in hot.CoveredLogicalPaths.Intersect(mechanical.CoveredLogicalPaths, StringComparer.Ordinal))
            if (!hot.ReadRequiredBytes(path).AsSpan().SequenceEqual(mechanical.ReadRequiredBytes(path)))
                throw new InvalidDataException("Overlapping HOT/mechanical original source changed: " + path);
    }
    internal void CloseCapture(object issuer, JsonObject custody)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (!_capturing || _phase != "Capturing") throw new InvalidOperationException("Joint capture cannot reopen.");
        _custody = custody.DeepClone().AsObject(); _capturing = false; _phase = "PreparationStarted";

    internal void RetainStage(object issuer, JointAttemptStage stage, object actualResult)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (_capturing || _delegated || _close is not null || (int)stage != _stages.Count || !_stages.TryAdd(stage, actualResult))
            throw new InvalidOperationException("Joint stage must be retained once before delegation.");
        _phase = stage is JointAttemptStage.Common or JointAttemptStage.Preflight ? "V2CommonSealed" : "Building";
    }
    internal void RetainContinuation(object issuer, object continuation)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (_capturing || _continuation is not null || _delegated) throw new InvalidOperationException("Joint continuation can be retained once.");
        _continuation = continuation;
    }
    internal void RetainReservation(object issuer, object reservation)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (_continuation is null || _reservation is not null || _delegated) throw new InvalidOperationException("Joint reservation can be retained once.");
        _reservation = reservation; _phase = "Reserved";
    }
    internal void MarkDelegated(object issuer)
    {
        RequireIssuer(issuer); RequireActualOwner(_files, _lease);
        if (_capturing || _delegated || _close is not null || !_stages.ContainsKey(JointAttemptStage.Preflight))
            throw new InvalidOperationException("Only the complete actual preflight can delegate this attempt.");
        _delegated = true; _phase = "Delegated";
    }
    internal void RecordClose(object issuer, AcceptedTurnAuthorityRegistry.JointUnattemptedCloseResult close)
    {
        RequireIssuer(issuer);
        if (_delegated || _close is not null) throw new InvalidOperationException("Attempt close cannot replace transaction ownership.");
        _capturing = false; _close = close; _phase = close.Disposition;
    }
    internal void Expire(object issuer)
    {
        RequireIssuer(issuer); _expired = true; _capturing = false;
        _hotOriginal = null; _hotEvidence = null;
    }
    internal JsonObject ExportDiagnostic() => new()
    {
        ["phase"] = _phase, ["closeDisposition"] = _close?.Disposition ?? (_delegated ? "UnavailableDelegated" : "UnavailableNotReserved"),
        ["delegated"] = _delegated, ["captureCanOpen"] = _capturing && !_expired,
        ["liveCapabilitiesExpired"] = _expired, ["fullSemanticAdmission"] = false,
        ["hasS"] = false, ["hasB"] = false, ["hasM3"] = false,
        ["binding"] = _binding.DeepClone(), ["custody"] = _custody.DeepClone()
    };
}

private MortalJointPublicationAttempt BeginCurrentJointAttempt(FileSystemManager.CanonicalWriteLease lease,
    ValidatedPendingTurnSnapshotContext frame, MortalJointRepairCheckpoint.RejectedCapture capture)
{
    if (_mortalJointPublicationAttempt is { } previous && previous.Live)
        throw new InvalidOperationException("A live joint attempt already owns this engine.");
    capture.EnsureCurrent(_fs, lease);
    var attempt = new MortalJointPublicationAttempt(JointAttemptIssuer, this, _fs, lease, frame, capture,
        HotBindingDiagnostic(_hotOrdinaryOriginal), HotCustodyDiagnostic(null));
    _mortalJointPublicationAttempt = attempt;
    try
    {
        attempt.RequireActualOwner(_fs, lease);
        return attempt;
    }
    catch
    {
        // The caller cannot receive this owner when Begin fails. Expire
        // exactly this unreserved registration without touching any debt.
        attempt.Expire(JointAttemptIssuer);
        throw;
    }
}

private async Task CaptureCurrentHotCustodyAsync(MortalJointPublicationAttempt attempt,
    FileSystemManager.CanonicalWriteLease lease)
{
    var read = _hotRepairReady;
    if (read is { Faulted: false, Status: "ConsumedReadyMatched", ReadyDeleteReturned: true, ReadyReleaseReturned: true })
    {
        try
        {
            await RecheckHotReadySourceAsync(lease, read, requireReadyAbsent: true);
            read.CurrentSourceRecheckSucceeded = true;
            attempt.RetainHotSource(JointAttemptIssuer, read.Source!.Snapshot, read.Source.Evidence);
        }
        catch (Exception error)
        {
            read.Fail(IsOptionalHotFailure(error) ? "SourceChanged" : "OwnerFailure");
            if (!IsOptionalHotFailure(error)) throw;
        }
    }
    attempt.CloseCapture(JointAttemptIssuer, HotCustodyDiagnostic(read));

private async Task<MortalJointRepairCanonicalRefresh> PublishCurrentMortalJointRepairAsync(
    ValidatedPendingTurnSnapshotContext frame, int expectedTurn,
    IReadOnlyDictionary<string, string> backups)
{
    if (_mortalJointPublicationAttempt is { Live: true })
        throw new InvalidOperationException("A live joint attempt already owns this engine.");
    if (!MatchesMortalJointRepairFrame(frame, expectedTurn) || !_mortalJointRepairCorrectionReady)
        throw new InvalidDataException("Joint canonical publication requires the actual corrected admitted frame.");
    if (_mortalJointRepairCanonicalRefresh is { Disposition: MortalJointRepairPublicationDisposition.Committed or
        MortalJointRepairPublicationDisposition.PublicationUncertain })
        throw new InvalidDataException("A retained joint committed/uncertain attempt requires its dedicated recovery route, not a second publication.");
    MortalJointRepairCanonicalRefresh result;
    MortalJointPublicationAttempt? attempt = null;
    try
    {
    await using (var lease = await _fs.AcquireCanonicalWriteLeaseAsync())
    {
        RequireOrdinaryJointRepairLease(lease);
        // The raw intake lease owns no plan. Reconstruct BOTH owners and the
        // still-confirmed original request here, under the canonical lease.
        var intake = await InspectOrdinaryMortalJointRepairAsync(lease, frame, expectedTurn);
        if (intake.Disposition != MortalJointRepairRawDisposition.Owned)
            return Retain(new(MortalJointRepairPublicationDisposition.PublicationUncertain, null, intake.Issues));
        await intake.ValidateCurrentAsync(_fs, lease, frame.SessionId, frame.RequestId,
            frame.Payload.ManifestPayloadHash, expectedTurn);
        var capture = await ReadCurrentJointRejectedCaptureAsync(lease, _mortalJointRepairCheckpoint!.ToJsonObject());
        attempt = BeginCurrentJointAttempt(lease, frame, capture);
        try
        {
            await CaptureCurrentHotCustodyAsync(attempt, lease);
            var preparation = await WoundAcceptedTurnPlanner.CreateJointRepairPreparationAsync(_fs, lease, capture);
            attempt.RetainStage(JointAttemptIssuer, JointAttemptStage.Preparation, preparation);
            if (!preparation.IsValid) return Refused(preparation.Issues);
            var continuation = preparation.Authority!;
            attempt.RetainContinuation(JointAttemptIssuer, continuation);
            var reservation = await AcceptedTurnAuthorityRegistry.ReserveMortalJointRepairPublicationAsync(_fs, lease, continuation);
            if (reservation.Authority is null || reservation.Status is not
                (MortalWoundTreatmentPublicationReservationStatus.Reserved or MortalWoundTreatmentPublicationReservationStatus.Exact))
                throw new InvalidDataException("The same joint owner could not reserve its exclusive publication slot.");
            var reservationAuthority = reservation.Authority;
            attempt.RetainReservation(JointAttemptIssuer, reservationAuthority);

        var baseline = await WoundAcceptedTurnPlanner.CreateJointRepairCommonBaselineAsync(
            _fs, lease, mechanical, bundle, anchors.Plan, continuation, reservationAuthority);
        if (!baseline.IsValid) return Refused(baseline.Issues);
        var resources = await WoundAcceptedTurnPlanner.CreateJointRepairResourcePublicationAsync(_fs, lease, baseline.Authority!);
        if (!resources.IsValid) return Refused(resources.Issues);
        // Freeze and authenticate progression BEFORE the common input,
        // cache fingerprint and take. No after-seal acknowledgement may
        // attach to the already-issued mechanics candidate.
        var progression = await CaptureMortalJointProgressionSourceAsync(lease, frame);
        var common = await WoundAcceptedTurnPlanner.CreateJointRepairCommonPlanAsync(_fs, lease, resources.Authority!, progression);
        if (!common.Success || common.Plan is not { } commonPlan) return Refused(common.Issues);
        attempt.RetainStage(JointAttemptIssuer, JointAttemptStage.Common, common);
        var bound = _normalizer.BindTo(lease);
        var preflight = await bound.PrevalidateJointRepairPublicationTransactionAsync() ??
            throw new InvalidDataException("The exact complete joint common plan was not preflighted.");
        if (preflight.Validated.Plan.InputFingerprint != commonPlan.InputFingerprint ||
            preflight.Validated.Plan.PreparedPlanFingerprint != commonPlan.PreparedPlanFingerprint)
            throw new InvalidDataException("Joint canonical preflight no longer selects the same complete common candidate.");
        // From here only the owning transaction can classify/compensate
        // attempted publication. A generic catch must never abort/rearm it.
        attempt.RetainStage(JointAttemptIssuer, JointAttemptStage.Preflight, preflight);
        attempt.MarkDelegated(JointAttemptIssuer);
        var published = await bound.NormalizeAndValidateJointRepairAsync(preflight, _validator, backups);
        result = Retain(new(published.Disposition, published.Plan, published.Issues));
        if (published.Disposition == MortalJointRepairPublicationDisposition.Committed)
        {
            // Retain Committed BEFORE this additional diagnostic read.
            // Its failure cannot reinterpret a finalized hold as rollback.
            var witness = await MortalQteDecisionPublication.ReadJointCompletedWitnessAsync(_fs, lease,
                frame.SessionId, frame.RequestId, frame.Payload.ManifestPayloadHash, expectedTurn);
            result = Retain(result with { Completed = witness });
        }
        lease.EnsureNoPendingLocalDecision();
    }
    catch (Exception error) when (error is not SessionReplacedException &&
        error is InvalidDataException or IOException or InvalidOperationException or ArgumentException or
            System.Text.Json.JsonException or AggregateException or OperationCanceledException)
    {
        CloseCurrentJointAttempt(attempt, lease);
        var existing = _mortalJointRepairCanonicalRefresh;
        result = Retain(new(existing?.Disposition == MortalJointRepairPublicationDisposition.Committed
            ? MortalJointRepairPublicationDisposition.Committed : MortalJointRepairPublicationDisposition.PublicationUncertain,
            existing?.Plan, JointRepairAdmissionIssue(error.Message), existing?.Completed));
    }

    MortalJointRepairCanonicalRefresh Refused(IReadOnlyList<ValidationIssue> issues)
    {
        CloseCurrentJointAttempt(attempt, lease);
        return Retain(new(MortalJointRepairPublicationDisposition.PublicationUncertain, null, issues));
    }
}
}
finally
{
    // Expiry follows the real await-using close, including its failure.
    attempt?.Expire(JointAttemptIssuer);
}

internal static PendingTurnSnapshotObservedReadResult ReadObservedCurrent(
    FileSystemManager fs,
    FileSystemManager.CanonicalWriteLease lease,
    IReadOnlyCollection<string> requiredLogicalPaths)
{
    var session = new OriginalSourceReadSession(fs, lease);
    var result = ReadCurrentCore(fs, lease, requiredLogicalPaths, session);
    return new PendingTurnSnapshotObservedReadResult(
        result.Success, result.Snapshot,
        result.Success ? session.Issue(result.Snapshot!) : null, result.Issues);
}

internal sealed class OriginalReadEvidence
{
    private readonly FrozenOriginalSource _source;
    private readonly PendingTurnSnapshotReadAuthority _snapshot;

    internal OriginalReadEvidence(object issuer, object frozenSource, PendingTurnSnapshotReadAuthority snapshot)
    {
        if (!ReferenceEquals(issuer, OriginalReadIssuer))
            throw new InvalidOperationException("Only the actual original reader can issue source evidence.");
        _source = frozenSource as FrozenOriginalSource
            ?? throw new InvalidOperationException("Original source closure is unavailable.");
        _snapshot = snapshot ?? throw new ArgumentNullException(nameof(snapshot));
    }

    internal void RequireCurrent(FileSystemManager fs, FileSystemManager.CanonicalWriteLease lease,
        PendingTurnSnapshotReadAuthority issuedSnapshot)
    {
        if (!ReferenceEquals(fs, _source.Files) || !ReferenceEquals(lease, _source.Lease) ||
            !ReferenceEquals(issuedSnapshot, _snapshot))
            throw new InvalidOperationException("Original evidence requires its exact owner, lease and issued snapshot.");
        var issues = new List<ValidationIssue>();
        if (!_source.Recheck(issues))
            throw new InvalidDataException(string.Join("; ", issues.Select(issue =>
                $"{issue.Code}: {issue.FilePath}: {issue.Actual}")));
    }

    // Every export is detached data. It cannot mint/rebind evidence after the lease ends.
    internal JsonObject ExportDiagnosticData()
    {
        var operations = new JsonArray();
        foreach (var operation in _source.Operations)
        {
            var row = new JsonObject
            {
                ["ordinal"] = operation.Ordinal,
                ["role"] = operation.Role.ToString(),
                ["path"] = operation.Path,
                ["logicalPath"] = operation.LogicalPath,
                ["isRepairRequest"] = operation.IsRepairRequest
            };
            if (operation.IsPresence) row["present"] = operation.Present;
            else
            {
                row["bytesBase64"] = operation.Bytes is null ? null : Convert.ToBase64String(operation.Bytes);
                row["rawHash"] = operation.Bytes is null ? null : PendingTurnSnapshotAuthority.ComputeSha256(operation.Bytes);
            }
            operations.Add(row);
        }
        return new JsonObject
        {
            ["generation"] = _source.GenerationId,
            ["generationBytesBase64"] = Convert.ToBase64String(_source.GenerationBytes),
            ["manifestRawHash"] = _source.RawHash(OriginalSourceRole.Manifest),
            ["authorityRawHash"] = _source.RawHash(OriginalSourceRole.DetachedAuthority),
            ["sessionId"] = _snapshot.SessionId,
            ["requestId"] = _snapshot.RequestId,
            ["snapshotToken"] = _snapshot.SnapshotToken,
            ["turnNumber"] = _snapshot.TurnNumber,
            ["realm"] = _snapshot.Realm,
            ["selectedLogicalPaths"] = Strings(_snapshot.CoveredLogicalPaths),
            ["absentLogicalPaths"] = Strings(_snapshot.AbsentLogicalPaths),
            ["declaredOriginalLogicalPaths"] = Strings(_snapshot.DeclaredOriginalLogicalPaths),
            ["operations"] = operations
