        repairResubmissionCompleted = true;
        var canonicalRepairErrors = errors
            .Where(issue => IsCanonicalStateRepairIssue(issue) &&
                            !IsPlayerFacingNeutralActorMemoryRepairIssue(issue))
            .ToArray();
